// TCRN-CROSS-STORY-479 R1, AC1, AC3 (MIN-227 D28): the SKILL.md of the Mana Orchestrate skill is
// generated by the engine for its own version and is never written by hand. It carries the
// finalized English description A as its frontmatter description, the navigation table (which
// engine verb to run at which moment), how to run a verb, the three-step routine, and one line
// that points to references/, which the host loads only for an install-type task. An everyday
// session loads this file and nothing else, so it stays under SKILL_MARKDOWN_BYTE_LIMIT bytes and
// keeps the wizard text out.
//
// Every verb the table names must be a verb of the engine the file is generated by: the caller
// passes the names of its command catalog, and a name the catalog does not carry refuses the whole
// rendering with SKILL_NAVIGATION_VERB_UNKNOWN, so a model never reads a verb that does not run.
// The navigation text also carries the decision rule of TCRN-CROSS-STORY-475 R4: a decision is
// recorded as soon as the model judges it one, and the reply ends by echoing its number.
//
// Every text is a constant in this module, and it reads no file: a packaged engine is one script,
// and a text kept anywhere else would not travel with it. tests/fixtures/skill/description-a.en.txt
// holds a copy of the finalized description, and tests/skill-render.test.mjs compares the two.

import { DEVICE_HOME_ENTRIES, DEVICE_HOME_ENVIRONMENT_VARIABLE } from "./device-home.js";
import { ENGINE_FILES } from "./engine-home.js";
import { isEngineVersion } from "./format-version.js";
import { BRAND, DIRECTORY } from "./names.js";

/** SKILL.md is always shorter than this many bytes (UTF-8). */
export const SKILL_MARKDOWN_BYTE_LIMIT = 6000;

export const SKILL_RENDER_REASON_CODES = Object.freeze([
  "SKILL_MARKDOWN_TOO_LARGE",
  "SKILL_NAVIGATION_VERB_UNKNOWN",
  "SKILL_VERSION_INVALID",
] as const);
export type SkillRenderReasonCode = typeof SKILL_RENDER_REASON_CODES[number];

export class SkillRenderError extends Error {
  readonly reasonCode: SkillRenderReasonCode;
  readonly details: Readonly<Record<string, string>>;

  constructor(reasonCode: SkillRenderReasonCode, message: string, details: Readonly<Record<string, string>> = {}) {
    super(message);
    this.name = "SkillRenderError";
    this.reasonCode = reasonCode;
    this.details = details;
  }
}

function fail(reasonCode: SkillRenderReasonCode, message: string, details: Readonly<Record<string, string>> = {}): never {
  throw new SkillRenderError(reasonCode, message, details);
}

/** The finalized English description A of the skill (MIN-227), word for word. */
export const SKILL_DESCRIPTION = "The Grail grants wishes; Mana Orchestrate makes the mana flow to the right place at the right moment. It brings Einzbern, project memory, into Claude Code and Codex: recall before you start, write results back to the work item, record decisions as minutes, keep lessons as cards. Where Einzbern is not installed yet, it is the wizard: install, restore, update, migrate, uninstall, health check. Use it whenever Einzbern, work items, knowledge cards, minutes, .ether, or Atelier come up, or when the user asks to install or update it." as const;

/** One row of the navigation table: at this moment, run these verbs, like this. */
export interface SkillNavigationEntry {
  readonly moment: string;
  readonly verbs: readonly string[];
  readonly action: string;
}

// The six moments of TCRN-CROSS-STORY-479 R1, in the order a task meets them.
export const SKILL_NAVIGATION: readonly SkillNavigationEntry[] = Object.freeze([
  {
    moment: "Starting work",
    verbs: ["recall"],
    action: "Before you start, run `recall --query \"<the task in a few words>\"` and read what comes back.",
  },
  {
    moment: "Need the full text",
    verbs: ["work-show", "minutes-show"],
    action: "Read the work item or the minutes whole (`--id` or `--external-key`) before relying on a headline.",
  },
  {
    moment: "Work is done",
    verbs: ["work-transition", "work-annotate"],
    action: "Write the result back to the work item: `work-annotate` records what was done, `work-transition` moves its status on.",
  },
  {
    moment: "A decision is made",
    verbs: ["minutes-record"],
    action: "As soon as you judge that something is a decision, record it: each decision gets its number, D1 to Dn. End your reply with `已记 <minutes key> Dn` for each one (`Recorded <minutes key> Dn` when the conversation is not in Chinese).",
  },
  {
    moment: "A lesson is learned",
    verbs: ["knowledge-create"],
    action: "Keep the lesson as a knowledge card. A card that replaces an older one names it with `--supersedes`.",
  },
  {
    moment: "UI design",
    verbs: ["settings-catalog"],
    action: "Before designing, read `design.authority` from `settings-catalog` and follow the design source it names.",
  },
].map((entry) => Object.freeze({ ...entry, verbs: Object.freeze([...entry.verbs]) })));

// Verbs the text names outside the table.
const OTHER_NAMED_VERBS: readonly string[] = Object.freeze(["commands"]);

/** Every engine verb SKILL.md names, the table's first and in its order, without repeats. */
export function skillNamedVerbs(): readonly string[] {
  return [...new Set([...SKILL_NAVIGATION.flatMap((entry) => entry.verbs), ...OTHER_NAMED_VERBS])];
}

export interface RenderSkillMarkdownInput {
  // The engine version the file is generated for.
  readonly version: string;
  // The names in that engine's command catalog.
  readonly catalogNames: readonly string[];
}

function navigationRow(entry: SkillNavigationEntry): string {
  return `| ${entry.moment} | ${entry.verbs.map((verb) => `\`${verb}\``).join(", ")} | ${entry.action} |`;
}

/**
 * SKILL.md for one engine version (TCRN-CROSS-STORY-479 R1): the frontmatter (name and the
 * finalized description A), the navigation table and how to run a verb, the three-step routine,
 * and the pointer to references/. Refuses a verb the catalog does not carry, a version that is not
 * a release version, and a result of SKILL_MARKDOWN_BYTE_LIMIT bytes or more.
 */
export function renderSkillMarkdown(input: RenderSkillMarkdownInput): string {
  if (!isEngineVersion(input.version)) {
    fail("SKILL_VERSION_INVALID", `${String(input.version)} is not an engine release version`, { version: String(input.version) });
  }
  const catalog = new Set(input.catalogNames);
  for (const verb of skillNamedVerbs()) {
    if (!catalog.has(verb)) {
      fail("SKILL_NAVIGATION_VERB_UNKNOWN", `${verb} is not a verb of engine ${input.version}; the navigation would name a verb that does not run`, { verb, version: input.version });
    }
  }
  const lines = [
    "---",
    `name: ${BRAND.helper.id}`,
    // A YAML double-quoted scalar: the description holds ": ", which a plain scalar cannot.
    `description: ${JSON.stringify(SKILL_DESCRIPTION)}`,
    "---",
    "",
    `# ${BRAND.helper.name}`,
    "",
    `Navigation for ${BRAND.engine.name} ${input.version}: which engine verb to run at which moment. The engine generated this file for that version; do not edit it by hand.`,
    "",
    "## Navigation",
    "",
    `Run a verb as \`node "<device directory>/${DEVICE_HOME_ENTRIES.engine}/${ENGINE_FILES.launcher}" <verb> --<flag> <value>\`. The device directory is \`~/${DIRECTORY.device}\`, or the directory \`${DEVICE_HOME_ENVIRONMENT_VARIABLE}\` names when it is set; if that file does not exist, ${BRAND.engine.name} is not installed on this device yet, so treat the request as an install. Each verb prints one JSON object with a \`reasonCode\`; \`commands\` lists every verb, and \`<verb> --help\` lists one verb's flags. Give \`--at\` the current UTC instant, \`YYYY-MM-DDTHH:MM:SSZ\`, wherever a verb takes it. Inside a registered project the library is found from the current directory; pass \`--workspace <library>\` only elsewhere.`,
    "",
    "| Moment | Verb | What to do |",
    "| --- | --- | --- |",
    ...SKILL_NAVIGATION.map(navigationRow),
    "",
    "## Three steps",
    "",
    `1. Install this skill: \`npx skills add tpmoonchefryan/mana-orchestrate\`, or ask the host to find the skill called ${BRAND.helper.name} and install it.`,
    `2. In the project, say "install ${BRAND.engine.name}". The wizard asks one screen of questions, confirms once, and sets up the engine and its hook for Claude Code and Codex together.`,
    `3. Then work as usual. Before every prompt the hook asks the engine for strongly relevant memory and puts it in the context; you record at the moments in the table above.`,
    "",
    "## Install-type tasks",
    "",
    "For an install, restore, update, repair, rollback, migration, uninstall or health check, read the matching file in `references/` (`install.md`, `restore.md`, `update.md`, `migrate.md`, `uninstall.md`, `doctor.md`); never load them for any other work.",
    "",
  ];
  const markdown = lines.join("\n");
  const bytes = Buffer.byteLength(markdown, "utf8");
  if (bytes >= SKILL_MARKDOWN_BYTE_LIMIT) {
    fail("SKILL_MARKDOWN_TOO_LARGE", `SKILL.md would be ${bytes} bytes; it must stay under ${SKILL_MARKDOWN_BYTE_LIMIT}`, { bytes: String(bytes), limit: String(SKILL_MARKDOWN_BYTE_LIMIT) });
  }
  return markdown;
}
